/bin/zsh -lc "python - <<'PY'
from invoice import Line, quote
from app import total
import pricing

assert total() == 6000
assert quote([Line('a', 4999, 1)], 'domestic', True) == {'subtotal_cents': 4999, 'discount_cents': 0, 'shipping_cents': 700, 'total_cents': 5699}
assert quote([Line('a', 5000, 1)], 'domestic', True) == {'subtotal_cents': 5000, 'discount_cents': 500, 'shipping_cents': 700, 'total_cents': 5200}
assert quote([Line('a', 5555, 1)], 'domestic', True) == {'subtotal_cents': 5555, 'discount_cents': 555, 'shipping_cents': 0, 'total_cents': 5000}
assert quote([Line('a', 5000, 1)], 'domestic') == {'subtotal_cents': 5000, 'discount_cents': 0, 'shipping_cents': 0, 'total_cents': 5000}
assert quote([Line('free', 0, 1)], 'international') == {'subtotal_cents': 0, 'discount_cents': 0, 'shipping_cents': 2000, 'total_cents': 2000}
assert quote([], 'international', True) == {'subtotal_cents': 0, 'discount_cents': 0, 'shipping_cents': 0, 'total_cents': 0}
old = pricing.RULES.copy()
try:
    pricing.RULES.update(domestic_cents=321, international_cents=1234, free_threshold=6000)
    assert quote([Line('a', 5555, 1)], 'domestic', True)['shipping_cents'] == 321
    assert quote([Line('free', 0, 1)], 'international')['shipping_cents'] == 1234
finally:
    pricing.RULES.clear()
    pricing.RULES.update(old)
for field, values in [('quantity', [True, 0, -1, 1.5]), ('unit_cents', [True, -1, 1.5])]:
    for value in values:
        kwargs = {'sku': 'a', 'unit_cents': 100, 'quantity': 1}
        kwargs[field] = value
        try:
            quote([Line(**kwargs)], 'domestic')
        except ValueError:
            pass
        else:
            raise AssertionError((field, value))
print('pricing behavior checks passed')
PY"
